ListDisabledDependencies.Command:
Start-Process powershell -ArgumentList '-NoExit','-NoProfile','-Command', @'
$svc=@{}; $grp=@{}
Get-ChildItem HKLM:\SYSTEM\CurrentControlSet\Services | %{
  $p=Get-ItemProperty $_.PSPath -ea 0
  $n=$_.PSChildName
  $svc[$n]=$p
  if($p.Group){ $grp[$p.Group]+=,$n }
}
$results = foreach($n in $svc.Keys){
  $s=$svc[$n].Start
  if($s -lt 0 -or $s -gt 3){ continue }
  $bad=@()
  foreach($d in $svc[$n].DependOnService){ if($svc[$d].Start -eq 4){ $bad+=$d } }
  foreach($g in $svc[$n].DependOnGroup){ foreach($m in $grp[$g]){ if($svc[$m].Start -eq 4){ $bad+="$g::$m" } } }
  if($bad){ [pscustomobject]@{Service=$n;Start=$s;DisabledDependencies=($bad -join ', ')} }
}
$results | Sort-Object Service | Format-Table -AutoSize
'@
